/** Functional interface allowing checked exceptions in lambda expressions. */
@FunctionalInterface
private interface ThrowingRunnable {
    void run() throws Exception;
}

/** Helper method that mimics JUnit 5's assertDoesNotThrow for JUnit 4 tests. */
private static void assertDoesNotThrow(ThrowingRunnable executable, String message) {
    try {
        executable.run();
    } catch (Throwable t) {
        fail(message + " - " + t);
    }
}

