/* Helper functional interfaces for custom assertDoesNotThrow */
@FunctionalInterface
private interface ThrowingRunnable {
    void run() throws Exception;
}

@FunctionalInterface
private interface ThrowingSupplier<T> {
    T get() throws Exception;
}

/**
 * Executes the given {@code ThrowingRunnable} and fails the test if an exception is thrown.
 */
private void assertDoesNotThrow(ThrowingRunnable runnable, String message) {
    try {
        runnable.run();
    } catch (Throwable t) {
        fail(message + ": " + t);
    }
}

/**
 * Executes the given {@code ThrowingSupplier} and returns its result,
 * failing the test if an exception is thrown.
 */
private <T> T assertDoesNotThrow(ThrowingSupplier<T> supplier, String message) {
    try {
        return supplier.get();
    } catch (Throwable t) {
        fail(message + ": " + t);
        return null; // unreachable, added to satisfy compiler
    }
}

/**
 * Common setup for tests dealing with the unterminated JSON object {@code {"a":"android"x}.
 */
private JsonReader setupReaderForUnterminatedObject() throws IOException {
    JsonReader reader = new JsonReader(reader("{\"a\":\"android\"x"));
    reader.setStrictness(Strictness.LENIENT);
    reader.beginObject();
    return reader;
}

/**
 * Verifies that the reader can successfully read the valid name and string values
 * from the malformed JSON before the error is encountered.
 */
@Test
public void testUnterminatedObject_readValidFields() {
    JsonReader reader = assertDoesNotThrow(
        this::setupReaderForUnterminatedObject,
        "Unexpected IOException occurred during the test");

    assertDoesNotThrow(() -> {
        assertThat(reader.nextName()).isEqualTo("a");
        assertThat(reader.nextString()).isEqualTo("android");
    }, "Unexpected IOException while reading valid fields");
}

/**
 * Verifies that a {@link MalformedJsonException} is thrown when peeking after the
 * malformed JSON has been partially consumed.
 */
@Test
public void testUnterminatedObject_exceptionOnPeek() {
    JsonReader reader = assertDoesNotThrow(
        this::setupReaderForUnterminatedObject,
        "Unexpected IOException occurred during the test");

    // Consume the valid parts of the JSON
    assertDoesNotThrow(() -> {
        assertThat(reader.nextName()).isEqualTo("a");
        assertThat(reader.nextString()).isEqualTo("android");
    }, "Unexpected IOException while reading valid fields");

    // Verify the expected exception on peek
    var e = assertThrows(MalformedJsonException.class, reader::peek);
    assertThat(e)
        .hasMessageThat()
        .isEqualTo(
            "Unterminated object at line 1 column 16 path $.a\n"
                + "See https://github.com/google/gson/blob/main/Troubleshooting.md#malformed-json");
