public void skipObjectValues() throws IOException {
    JsonReader reader = factory.create("{\"a\":1,\"b\":2}");
    reader.beginObject();

    assertWithMessage("Previous path after beginObject should be $.")
        .that(reader.getPreviousPath())
        .isEqualTo("$.");

    assertWithMessage("Current path after beginObject should be $.")
        .that(reader.getPath())
        .isEqualTo("$.");

    String unused1 = reader.nextName(); // reads "a"
    reader.skipValue();                  // skips value 1

    assertWithMessage("Previous path after skipping value of 'a' should be $.a")
        .that(reader.getPreviousPath())
        .isEqualTo("$.a");

    assertWithMessage("Current path after skipping value of 'a' should be $.a")
        .that(reader.getPath())
        .isEqualTo("$.a");

    String unused2 = reader.nextName(); // reads "b"

    assertWithMessage("Previous path after reading name 'b' should be $.b")
        .that(reader.getPreviousPath())
        .isEqualTo("$.b");

    assertWithMessage("Current path after reading name 'b' should be $.b")
        .that(reader.getPath())
        .isEqualTo("$.b");
}

