@Test
void testMalformedNumbers() {
    assertDoesNotThrow(this::assertAllMalformedNumbersThrow,
        "Unexpected IOException during malformed number test");
}

private void assertAllMalformedNumbersThrow() {
    String[] malformedNumbers = {
        "some text",
        "",
        ".",
        "00",
        "01",
        "-00",
        "-",
        "--1",
        "+1", // plus sign is not allowed for integer part
        "+",
        "1,0",
        "1,000",
        "0.", // decimal digit is required
        ".1", // integer part is required
        "e1",
        ".e1",
        ".1e1",
        "1e-",
        "1e+",
        "1e--1",
        "1e+-1",
        "1e1e1",
        "1+e1",
        "1e1.0",
    };
    for (String malformedNumber : malformedNumbers) {
        assertMalformedNumberThrows(malformedNumber);
    }
}

private void assertMalformedNumberThrows(String malformedNumber) {
    JsonWriter jsonWriter = new JsonWriter(new StringWriter());
    IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
        () -> jsonWriter.value(new LazilyParsedNumber(malformedNumber)));
    assertThat(e).hasMessageThat()
        .isEqualTo("String created by class com.google.gson.internal.LazilyParsedNumber is not a valid"
            + " JSON number: " + malformedNumber);
}

