/**
 * Parameterized test for {@code Document.wholeText()} covering the three
 * distinct scenarios originally combined in a single test method.
 */
@ParameterizedTest(name = "wholeText case {index}")
@MethodSource("wholeTextProvider")
void testWholeText(String html, String expected) {
    assertWholeText(html, expected);
}

/** Provides the HTML/input pairs for the {@code testWholeText} parameterized test. */
private static Stream<Arguments> wholeTextProvider() {
    return Stream.of(
        arguments("<p> Hello\nthere &nbsp;  </p>", " Hello\nthere \u00A0  "),
        arguments("<p>Hello  \n  there</p>", "Hello  \n  there"),
        arguments("<p>Hello  <div>\n  there</div></p>", "Hello  \n  there")
    );
}

