@Test public void createsFormData() {
    String html = "<form><input name='one' value='two'><select name='three'><option value='not'>" +
            "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>" +
            "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>" +
            "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>" +
            "<input name='ten' value='text' disabled>" +
            "<input name='eleven' value='text' type='button'>" +
            "</form>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    List<Connection.KeyVal> data = form.formData();

    assertEquals(6, data.size());
    assertEquals("one=two", data.get(0).toString());
    assertEquals("three=four", data.get(1).toString());
    assertEquals("three=five", data.get(2).toString());
    assertEquals("six=seven", data.get(3).toString());
    assertEquals("seven=on", data.get(4).toString()); // set
    assertEquals("eight=on", data.get(5).toString()); // default
    // nine should not appear, not checked checkbox
    // ten should not appear, disabled
    // eleven should not appear, button
}

proposals.refactored:
private static final int EXPECTED_FORM_DATA_SIZE = 6;

private List<Connection.KeyVal> getFormData() {
    String html = "<form><input name='one' value='two'><select name='three'><option value='not'>" +
            "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>" +
            "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>" +
            "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>" +
            "<input name='ten' value='text' disabled>" +
            "<input name='eleven' value='text' type='button'>" +
            "</form>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    return form.formData();
}

@Test
public void createsFormData_totalSize() {
    List<Connection.KeyVal> data = getFormData();
    assertEquals("Form data should contain the expected number of entries",
                 EXPECTED_FORM_DATA_SIZE, data.size());
}

@Test
public void createsFormData_entries() {
    List<Connection.KeyVal> data = getFormData();

    String actual0 = data.get(0).toString();
    assertEquals("First entry should be 'one=two'", "one=two", actual0);

    String actual1 = data.get(1).toString();
    assertEquals("Second entry should be 'three=four'", "three=four", actual1);

    String actual2 = data.get(2).toString();
    assertEquals("Third entry should be 'three=five'", "three=five", actual2);

    String actual3 = data.get(3).toString();
    assertEquals("Fourth entry should be 'six=seven'", "six=seven", actual3);

    String actual4 = data.get(4).toString();
    assertEquals("Fifth entry should be 'seven=on' (selected radio)", "seven=on", actual4);

    String actual5 = data.get(5).toString();
    assertEquals("Sixth entry should be 'eight=on' (default checkbox)", "eight=on", actual5);
}

@Test
public void createsFormData_exclusions() {
    List<Connection.KeyVal> data = getFormData();

    boolean containsNine = data.stream().anyMatch(kv -> "nine".equals(kv.key()));
    assertFalse("Form data should not contain entry for 'nine' (unchecked checkbox)", containsNine);

    boolean containsTen = data.stream().anyMatch(kv -> "ten".equals(kv.key()));
    assertFalse("Form data should not contain entry for 'ten' (disabled input)", containsTen);

    boolean containsEleven = data.stream().anyMatch(kv -> "eleven".equals(kv.key()));
    assertFalse("Form data should not contain entry for 'eleven' (button input)", containsEleven);
}

